            return True
        m = eqs[-1]
        a, op, b, c = float(m.group(1)), m.group(2), float(m.group(3)), float(m.group(4))
        if abs(c - f) > 1e-9:
            return True
        if op in 'xX*':
            r = a * b
        elif op == '+':
            r = a + b
        elif op == '-':
            r = a - b
        else:
            if b == 0:
                return True
            r = a / b
        if abs(r - c) > max(0.01 * abs(c), 0.01) + 1e-9:
            return False
        return True
    except Exception:
        return True

